use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let mut tmp: i32 = 0;

    {
        let permit = s.acquire();
        tmp = 1;
        permit.release();
    }

    {
        let permit = s.acquire();
        tmp = 2;
        permit.release();
    }
}

fn w2(s: Arc<Semaphore>) {
    let mut tmp: i32 = 0;

    {
        let permit = s.acquire();
        tmp = 3;
        permit.release();
    }

    {
        let permit = s.acquire();
        tmp = 4;
        permit.release();
    }
}

fn main() {
    let s = Semaphore::new(1);

    let s1 = Arc::clone(&s);
    let t1 = thread::spawn(move || w1(s1));

    let s2 = Arc::clone(&s);
    let t2 = thread::spawn(move || w2(s2));

    t1.join().unwrap();
    t2.join().unwrap();

    println!("DONE done=1");
}
